"use client";

import { useApp } from "@/lib/store";

export function TopBar() {
  const spec = useApp((s) => s.spec);
  const enabled = useApp((s) => s.enabledBands);
  const toggleBand = useApp((s) => s.toggleBand);
  const running = useApp((s) => s.running);
  const jobs = useApp((s) => s.jobs);
  const reset = useApp((s) => s.reset);
  const done = jobs.filter((j) => j.status === "complete").length;

  return (
    <header className="flex h-12 shrink-0 items-center gap-4 border-b border-slate-800 bg-slate-950 px-4">
      <div className="flex items-baseline gap-2">
        <span className="text-sm font-semibold tracking-tight text-slate-100">
          Antenna Placement Studio
        </span>
        <span className="font-mono text-[10px] text-slate-500">{spec.device_id}</span>
      </div>

      <div className="ml-4 flex items-center gap-1">
        {spec.requirements.bands.map((b) => {
          const on = enabled.includes(b.id);
          return (
            <button
              key={b.id}
              onClick={() => toggleBand(b.id)}
              className={`flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] transition ${
                on
                  ? "border-slate-600 bg-slate-800 text-slate-100"
                  : "border-slate-800 text-slate-600 hover:text-slate-400"
              }`}
            >
              <span
                className="h-1.5 w-1.5 rounded-full"
                style={{ background: on ? b.color : "#475569" }}
              />
              {b.name}
            </button>
          );
        })}
      </div>

      <div className="ml-auto flex items-center gap-3">
        {!!jobs.length && (
          <span className="font-mono text-[10px] text-slate-500">
            {done}/{jobs.length} simulations
            {running && <span className="ml-1 text-sky-400">running</span>}
          </span>
        )}
        <button
          onClick={reset}
          className="rounded-md border border-slate-700 px-2.5 py-1 text-[10px] text-slate-400 hover:border-slate-500 hover:text-slate-200"
        >
          Clear run
        </button>
      </div>
    </header>
  );
}

"use client";

import { create } from "zustand";
import { anchors, phoneV1 } from "./device";
import { generateCandidates } from "./rf";
import type {
  AgentMessage,
  Anchor,
  BandRequirement,
  Candidate,
  DeviceSpec,
  Job,
  SimResult,
} from "./types";

export type ViewMode = "system" | "focus";
export type AgentKind = "mock" | "devin";
/** Which engine produced the run on screen. `null` until a run starts. */
export type RunSource = "backend" | "heuristic" | null;

interface AppState {
  spec: DeviceSpec;
  anchors: Anchor[];
  /** Backend device id after a .blend upload; null = the built-in Handset A. */
  deviceId: string | null;
  uploading: boolean;

  enabledBands: string[];
  focusBand: string | null;
  viewMode: ViewMode;

  explode: number;
  hidden: string[];
  selectedComponent: string | null;
  hoveredComponent: string | null;

  showKeepouts: boolean;
  showHeatmap: boolean;
  showPins: boolean;
  showIsolation: boolean;
  showLabels: boolean;
  showGrid: boolean;

  candidates: Candidate[];
  results: Record<string, SimResult>;
  jobs: Job[];
  placements: Record<string, string>;
  isolation: { a: string; b: string; db: number }[];
  selectedCandidate: string | null;

  prompt: string;
  messages: AgentMessage[];
  runId: string | null;
  running: boolean;
  planning: boolean;
  error: string | null;
  /** mock = offline heuristic agent on the backend; devin = the real one. */
  agent: AgentKind;
  source: RunSource;
  engine: string | null;
  warning: string | null;

  /** URL of a user-supplied .glb; overrides the procedural handset. */
  modelUrl: string | null;
  modelName: string | null;
  setModel: (url: string | null, name: string | null) => void;

  updateBand: (id: string, patch: Partial<BandRequirement>) => void;
  updateSar: (standard: string) => void;
  updateBoard: (patch: Partial<DeviceSpec["board"]>) => void;

  toggleBand: (id: string) => void;
  setFocusBand: (id: string | null) => void;
  setViewMode: (m: ViewMode) => void;
  setExplode: (v: number) => void;
  toggleHidden: (name: string) => void;
  isolateComponent: (name: string | null) => void;
  selectComponent: (name: string | null) => void;
  hoverComponent: (name: string | null) => void;
  toggle: (
    key:
      | "showKeepouts"
      | "showHeatmap"
      | "showPins"
      | "showIsolation"
      | "showLabels"
      | "showGrid",
  ) => void;
  selectCandidate: (id: string | null) => void;
  setPrompt: (p: string) => void;
  setAgent: (a: AgentKind) => void;
  /** Upload a .blend to the backend; the viewer switches to its device.glb. */
  uploadBlend: (blend: File, materials?: File | null) => Promise<void>;
  startRun: () => Promise<void>;
  /** Mid-run note to the agent (backend runs only). */
  sendNote: (text: string) => Promise<void>;
  poll: () => Promise<void>;
  reset: () => void;
}

const DEFAULT_BANDS = ["lte_low", "gps_l1", "wifi24", "n78"];

export const useApp = create<AppState>((set, get) => ({
  spec: phoneV1,
  anchors,
  deviceId: null,
  uploading: false,

  enabledBands: DEFAULT_BANDS,
  focusBand: null,
  viewMode: "system",

  explode: 0,
  hidden: [],
  selectedComponent: null,
  hoveredComponent: null,

  showKeepouts: true,
  showHeatmap: false,
  showPins: true,
  showIsolation: true,
  showLabels: true,
  showGrid: true,

  candidates: generateCandidates(phoneV1, DEFAULT_BANDS),
  results: {},
  jobs: [],
  placements: {},
  isolation: [],
  selectedCandidate: null,

  prompt:
    "Where should the antennas be placed in this phone? Pick the type, target band and expected performance for each, and respect the keep-out and SAR limits.",
  messages: [],
  runId: null,
  running: false,
  planning: false,
  error: null,
  agent: "mock",
  source: null,
  engine: null,
  warning: null,

  modelUrl: null,
  modelName: null,
  setModel: (url, name) => set({ modelUrl: url, modelName: name }),

  updateBand: (id, patch) => {
    const spec: DeviceSpec = {
      ...get().spec,
      requirements: {
        ...get().spec.requirements,
        bands: get().spec.requirements.bands.map((b) =>
          b.id === id ? { ...b, ...patch } : b,
        ),
      },
    };
    set({ spec, candidates: generateCandidates(spec, get().enabledBands) });
  },

  updateSar: (standard) => {
    const preset =
      standard === "ICNIRP"
        ? { standard: "ICNIRP", w_per_kg: 2.0, mass_g: 10 }
        : { standard: "FCC", w_per_kg: 1.6, mass_g: 1 };
    set({
      spec: {
        ...get().spec,
        requirements: { ...get().spec.requirements, sar_limit: preset },
      },
    });
  },

  updateBoard: (patch) =>
    set({ spec: { ...get().spec, board: { ...get().spec.board, ...patch } } }),

  toggleBand: (id) => {
    const next = get().enabledBands.includes(id)
      ? get().enabledBands.filter((b) => b !== id)
      : [...get().enabledBands, id];
    const spec = get().spec;
    const ordered = spec.requirements.bands
      .map((b) => b.id)
      .filter((b) => next.includes(b));
    set({
      enabledBands: ordered,
      // preview pins before a run; a backend run replaces them with its own
      candidates: get().deviceId ? [] : generateCandidates(spec, ordered),
      focusBand: get().focusBand && ordered.includes(get().focusBand!) ? get().focusBand : null,
    });
  },

  setFocusBand: (id) =>
    set({ focusBand: id, viewMode: id ? "focus" : "system" }),
  setViewMode: (m) =>
    set({
      viewMode: m,
      focusBand:
        m === "focus" ? (get().focusBand ?? get().enabledBands[0] ?? null) : null,
    }),
  setExplode: (v) => set({ explode: v }),
  toggleHidden: (name) =>
    set({
      hidden: get().hidden.includes(name)
        ? get().hidden.filter((n) => n !== name)
        : [...get().hidden, name],
    }),
  isolateComponent: (name) =>
    set({
      hidden: name
        ? get().spec.components.map((c) => c.name).filter((n) => n !== name)
        : [],
      selectedComponent: name,
    }),
  selectComponent: (name) => set({ selectedComponent: name }),
  hoverComponent: (name) => set({ hoveredComponent: name }),
  toggle: (key) => set({ [key]: !get()[key] } as Partial<AppState>),
  selectCandidate: (id) => set({ selectedCandidate: id }),
  setPrompt: (p) => set({ prompt: p }),
  setAgent: (a) => set({ agent: a }),

  uploadBlend: async (blend, materials) => {
    const form = new FormData();
    form.append("blend", blend, blend.name);
    if (materials) form.append("materials", materials, materials.name);
    set({ uploading: true, error: null });
    try {
      const res = await fetch("/api/device", { method: "POST", body: form });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? `upload failed (${res.status})`);
      const spec: DeviceSpec = body.spec;
      const enabled = get().enabledBands.filter((id) =>
        spec.requirements.bands.some((b) => b.id === id),
      );
      set({
        deviceId: body.deviceId,
        spec,
        anchors: body.anchors,
        enabledBands: enabled,
        candidates: [],
        hidden: [],
        selectedComponent: null,
        modelUrl: body.glbUrl,
        modelName: blend.name,
      });
      get().reset();
    } catch (e) {
      set({ error: String(e instanceof Error ? e.message : e) });
    } finally {
      set({ uploading: false });
    }
  },

  startRun: async () => {
    const { enabledBands, prompt, agent, deviceId } = get();
    if (!enabledBands.length) {
      set({ error: "Select at least one band before running." });
      return;
    }
    set({
      running: true,
      planning: true,
      error: null,
      warning: null,
      source: null,
      engine: null,
      results: {},
      jobs: [],
      placements: {},
      isolation: [],
      messages: [
        {
          id: "u0",
          role: "user",
          kind: "text",
          text: prompt,
          ts: Date.now(),
        },
      ],
    });
    try {
      const res = await fetch("/api/run", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          prompt,
          bands: enabledBands,
          agent,
          deviceId,
          overrides: {
            sar_limit: get().spec.requirements.sar_limit,
            bands: Object.fromEntries(
              get().spec.requirements.bands.map((b) => [
                b.id,
                {
                  clearance_mm: b.clearance_mm,
                  s11_db_max: b.s11_db_max,
                  efficiency_min: b.efficiency_min,
                },
              ]),
            ),
          },
        }),
      });
      if (!res.ok) throw new Error((await res.json()).error ?? "run failed");
      const { runId, source, warning } = await res.json();
      set({
        runId,
        source: source ?? null,
        warning: warning ?? null,
        messages: warning
          ? [
              ...get().messages,
              { id: "w0", role: "agent", kind: "step", text: `Warning: ${warning}`, ts: Date.now() },
            ]
          : get().messages,
      });
      await get().poll();
    } catch (e) {
      set({ running: false, planning: false, error: String(e) });
    }
  },

  sendNote: async (text) => {
    const runId = get().runId;
    if (!runId || !text.trim()) return;
    const res = await fetch("/api/run", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ runId, text }),
    });
    if (!res.ok) {
      set({ error: (await res.json()).error ?? "note not delivered" });
      return;
    }
    set({ error: null });
    await get().poll();
  },

  poll: async () => {
    const runId = get().runId;
    if (!runId) return;
    const res = await fetch(`/api/run?runId=${runId}`);
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      set({ running: false, error: body.error ?? "run snapshot unavailable" });
      return;
    }
    const snap = await res.json();
    // The user's prompt is local; backend runs echo only mid-run notes.
    const userMsg = get().messages.find((m) => m.id === "u0");
    const warn = get().messages.find((m) => m.id === "w0");
    const head = [userMsg, warn].filter(Boolean) as AgentMessage[];
    const placements: Record<string, string> = snap.placements ?? {};
    set({
      jobs: snap.jobs ?? [],
      results: snap.results ?? {},
      placements,
      isolation: snap.isolation ?? [],
      candidates: snap.candidates ?? [],
      planning: !!snap.planning,
      running: !snap.done,
      source: snap.source ?? get().source,
      engine: snap.engine ?? get().engine,
      messages: [...head, ...(snap.messages ?? [])],
      error: snap.status === "failed" ? "run failed — see the agent feed" : get().error,
      selectedCandidate:
        get().selectedCandidate ?? (Object.values(placements)[0] as string | undefined) ?? null,
    });
  },

  reset: () =>
    set({
      runId: null,
      running: false,
      planning: false,
      jobs: [],
      results: {},
      placements: {},
      isolation: [],
      messages: [],
      selectedCandidate: null,
      source: null,
      engine: null,
      warning: null,
      error: null,
      candidates: get().deviceId ? [] : generateCandidates(get().spec, get().enabledBands),
    }),
}));
=====types
// Contracts shared with the simulation + agent workstreams.
// Mirrors the JSON schemas in deep_research_on_challenge.md §5.
// All geometry is in millimetres, origin at the bottom-left-back corner of the device.

export type Vec3 = [number, number, number];
export type Bbox = [Vec3, Vec3]; // [min, max]

export type EmClass = "pec" | "lossy_metal" | "dielectric" | "air";

export interface DeviceComponent {
  /** Must match the glTF node name exported from Blender. */
  name: string;
  label: string;
  em: EmClass;
  epsilon_r?: number;
  loss_tangent?: number;
  bbox_mm: Bbox;
  /** Display-only hints for the viewer. */
  color: string;
  opacity?: number;
  metalness?: number;
  roughness?: number;
  /** Shell parts render as rounded frames rather than plain boxes. */
  shape?: "box" | "frame" | "glass";
  /** Explode direction in scene space. */
  explode?: Vec3;
}

export interface BandRequirement {
  id: string;
  name: string;
  short: string;
  service: string;
  f_low_ghz: number;
  f_high_ghz: number;
  /** Minimum antenna clearance (keep-out radius) in mm. */
  clearance_mm: number;
  s11_db_max: number;
  efficiency_min: number;
  /** Preferred antenna types, best first. */
  antenna_types: AntennaType[];
  /** Region weighting: how much this band likes each perimeter region. */
  region_pref: Record<RegionId, number>;
  color: string;
}

export type AntennaType =
  | "IFA"
  | "PIFA"
  | "monopole"
  | "loop"
  | "frame_slot"
  | "patch_array"
  | "ceramic_chip";

export type RegionId = "bottom" | "top" | "left" | "right";

export interface DeviceSpec {
  device_id: string;
  name: string;
  board: {
    size_mm: Vec3;
    stackup: string;
    epsilon_r: number;
    loss_tangent: number;
  };
  enclosure: { back: string; frame: string; epsilon_r_back: number };
  components: DeviceComponent[];
  requirements: {
    bands: BandRequirement[];
    vswr_max: number;
    isolation_db_max: number;
    sar_limit: { standard: string; w_per_kg: number; mass_g: number };
  };
}

export interface Anchor {
  id: string;
  label: string;
  region: RegionId;
  /** Centre of the candidate antenna volume, in mm. */
  pos_mm: Vec3;
  /** Outward normal along the device surface. */
  outward: Vec3;
  corner: boolean;
}

export interface Candidate {
  candidate_id: string;
  anchor_id: string;
  band_id: string;
  antenna_type: AntennaType;
  position_mm: Vec3;
  feed_point_mm: Vec3;
  length_mm: number;
  orientation: "edge" | "corner" | "face";
  keepout_mm: Bbox;
  /** Pre-simulation heuristic score, 0..1. */
  prior: number;
  rationale: string;
}

export interface SimResult {
  candidate_id: string;
  status: "queued" | "running" | "complete" | "failed";
  runtime_s: number;
  s11_curve: { f_ghz: number; s11_db: number }[];
  s11_min_db: number;
  resonant_ghz: number;
  bandwidth_mhz: number;
  efficiency: number;
  peak_gain_dbi: number;
  vswr: number;
  sar_w_per_kg: number;
  meets_requirements: boolean;
  notes: string;
}

export interface Job {
  job_id: string;
  candidate_id: string;
  band_id: string;
  status: "queued" | "running" | "complete" | "failed";
  progress: number;
  started_at?: number;
  finished_at?: number;
}

export interface AgentMessage {
  id: string;
  role: "user" | "agent";
  kind: "text" | "step" | "result";
  text: string;
  ts: number;
}

"use client";

import { useRef } from "react";
import { useApp } from "@/lib/store";

function NumberField({
  label,
  value,
  step = 1,
  suffix,
  onChange,
}: {
  label: string;
  value: number;
  step?: number;
  suffix?: string;
  onChange: (v: number) => void;
}) {
  return (
    <label className="flex items-center justify-between gap-2 py-0.5">
      <span className="text-[10px] text-slate-400">{label}</span>
      <span className="flex items-center gap-1">
        <input
          type="number"
          value={value}
          step={step}
          onChange={(e) => onChange(parseFloat(e.target.value))}
          className="w-16 rounded border border-slate-700 bg-slate-900 px-1.5 py-0.5 text-right font-mono text-[10px] text-slate-200 outline-none focus:border-sky-500"
        />
        {suffix && (
          <span className="w-8 font-mono text-[9px] text-slate-500">{suffix}</span>
        )}
      </span>
    </label>
  );
}

export function SpecPanel() {
  const spec = useApp((s) => s.spec);
  const enabled = useApp((s) => s.enabledBands);
  const toggleBand = useApp((s) => s.toggleBand);
  const updateBand = useApp((s) => s.updateBand);
  const updateSar = useApp((s) => s.updateSar);
  const updateBoard = useApp((s) => s.updateBoard);
  const focusBand = useApp((s) => s.focusBand);
  const setFocusBand = useApp((s) => s.setFocusBand);
  const setModel = useApp((s) => s.setModel);
  const modelName = useApp((s) => s.modelName);
  const uploadBlend = useApp((s) => s.uploadBlend);
  const uploading = useApp((s) => s.uploading);
  const deviceId = useApp((s) => s.deviceId);
  const fileRef = useRef<HTMLInputElement>(null);

  return (
    <>
      <section className="border-b border-slate-800 px-3 py-2">
        <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-400">
          Device
        </h2>
        <div className="rounded-md border border-slate-800 bg-slate-900/60 p-2">
          <div className="text-xs text-slate-200">{spec.name}</div>
          <div className="mt-1 font-mono text-[10px] text-slate-500">
            {spec.device_id} - {spec.enclosure.frame} frame, {spec.enclosure.back} back
          </div>
          <div className="mt-2 space-y-0.5">
            <NumberField
              label="Board er"
              value={spec.board.epsilon_r}
              step={0.1}
              onChange={(v) => updateBoard({ epsilon_r: v })}
            />
            <NumberField
              label="Board tan-d"
              value={spec.board.loss_tangent}
              step={0.001}
              onChange={(v) => updateBoard({ loss_tangent: v })}
            />
          </div>
          <input
            ref={fileRef}
            type="file"
            accept=".blend,.glb,.gltf"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0];
              e.target.value = "";
              if (!f) return;
              // .blend goes through the backend (extraction + classification);
              // a .glb is display-only and never reaches the solver.
              if (f.name.toLowerCase().endsWith(".blend")) void uploadBlend(f);
              else setModel(URL.createObjectURL(f), f.name);
            }}
          />
          <div className="mt-2 flex items-center gap-2">
            <button
              onClick={() => fileRef.current?.click()}
              disabled={uploading}
