  dashed,
}: {
  bbox: Bbox;
  color: string;
  opacity: number;
  dashed?: boolean;
}) {
  const size = sceneSize(bbox);
  const center = sceneCenter(bbox);
  return (
    <mesh position={center}>
      <boxGeometry args={size} />
      <meshBasicMaterial
        color={color}
        transparent
        opacity={opacity}
