"use client";

import { create } from "zustand";
import { anchors, phoneV1 } from "./device";
import type {
  AgentMessage,
  Anchor,
  Candidate,
  DeviceSpec,
  Job,
  SimResult,
} from "./types";

export type ViewMode = "system" | "focus";
export type AgentKind = "mock" | "devin";
export type Layer = "showKeepouts" | "showPins" | "showLabels";

interface AppState {
  // ---- device
  spec: DeviceSpec;
  anchors: Anchor[];
  /** Backend device id after a .blend upload; null = the built-in Handset A. */
  deviceId: string | null;
  uploading: boolean;
  /** URL of a user-supplied .glb; overrides the procedural handset. */
  modelUrl: string | null;
  modelName: string | null;

  // ---- viewer
  enabledBands: string[];
  focusBand: string | null;
  viewMode: ViewMode;
  explode: number;
  hidden: string[];
  selectedComponent: string | null;
  hoveredComponent: string | null;
  showKeepouts: boolean;
  showPins: boolean;
  showLabels: boolean;

  // ---- run
  prompt: string;
  /** mock = the backend's offline heuristic agent; devin = the real one. */
  agent: AgentKind;
  runId: string | null;
  running: boolean;
  planning: boolean;
  engine: string | null;
  error: string | null;
  candidates: Candidate[];
  results: Record<string, SimResult>;
  jobs: Job[];
  placements: Record<string, string>;
  selectedCandidate: string | null;
  messages: AgentMessage[];
  /** The agent's report.md, fetched once the run has finished. */
  report: string | null;

  // ---- actions
  setModel: (url: string | null, name: string | null) => void;
  uploadBlend: (blend: File, materials?: File | null) => Promise<void>;
  toggleBand: (id: string) => void;
  setFocusBand: (id: string | null) => void;
  setViewMode: (m: ViewMode) => void;
  setExplode: (v: number) => void;
  toggleHidden: (name: string) => void;
  isolateComponent: (name: string | null) => void;
  selectComponent: (name: string | null) => void;
  hoverComponent: (name: string | null) => void;
  toggle: (key: Layer) => void;
  selectCandidate: (id: string | null) => void;
  setPrompt: (p: string) => void;
  setAgent: (a: AgentKind) => void;
  startRun: () => Promise<void>;
  /** Mid-run note to the agent. */
  sendNote: (text: string) => Promise<void>;
  poll: () => Promise<void>;
  reset: () => void;
}

const DEFAULT_BANDS = ["lte_low", "gps_l1", "wifi24", "n78"];

const EMPTY_RUN = {
  runId: null,
  running: false,
  planning: false,
  engine: null,
  error: null,
  candidates: [] as Candidate[],
  results: {} as Record<string, SimResult>,
  jobs: [] as Job[],
  placements: {} as Record<string, string>,
  selectedCandidate: null,
  messages: [] as AgentMessage[],
  report: null,
};

export const useApp = create<AppState>((set, get) => ({
  spec: phoneV1,
  anchors,
  deviceId: null,
  uploading: false,
  modelUrl: null,
  modelName: null,

  enabledBands: DEFAULT_BANDS,
  focusBand: null,
  viewMode: "system",
  explode: 0,
  hidden: [],
  selectedComponent: null,
  hoveredComponent: null,
  showKeepouts: true,
  showPins: true,
  showLabels: true,

  prompt:
    "Where should the antennas be placed in this phone? Pick the type, target band and expected performance for each, and respect the keep-out limits.",
  agent: "mock",
  ...EMPTY_RUN,

  setModel: (url, name) => set({ modelUrl: url, modelName: name }),

  uploadBlend: async (blend, materials) => {
    const form = new FormData();
    form.append("blend", blend, blend.name);
    if (materials) form.append("materials", materials, materials.name);
    set({ uploading: true, error: null });
    try {
      const res = await fetch("/api/device", { method: "POST", body: form });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? `upload failed (${res.status})`);
      const spec: DeviceSpec = body.spec;
      set({
        deviceId: body.deviceId,
        spec,
        anchors: body.anchors,
        enabledBands: get().enabledBands.filter((id) =>
          spec.requirements.bands.some((b) => b.id === id),
        ),
        hidden: [],
        selectedComponent: null,
        modelUrl: body.glbUrl,
        modelName: blend.name,
        ...EMPTY_RUN,
      });
    } catch (e) {
      set({ error: e instanceof Error ? e.message : String(e) });
    } finally {
      set({ uploading: false });
    }
  },

  toggleBand: (id) => {
    const next = get().enabledBands.includes(id)
      ? get().enabledBands.filter((b) => b !== id)
      : [...get().enabledBands, id];
    const ordered = get()
      .spec.requirements.bands.map((b) => b.id)
      .filter((b) => next.includes(b));
    const focus = get().focusBand;
    set({
      enabledBands: ordered,
      focusBand: focus && ordered.includes(focus) ? focus : null,
    });
  },

  setFocusBand: (id) => set({ focusBand: id, viewMode: id ? "focus" : "system" }),
  setViewMode: (m) =>
    set({
      viewMode: m,
      focusBand: m === "focus" ? (get().focusBand ?? get().enabledBands[0] ?? null) : null,
    }),
  setExplode: (v) => set({ explode: v }),
  toggleHidden: (name) =>
    set({
      hidden: get().hidden.includes(name)
        ? get().hidden.filter((n) => n !== name)
        : [...get().hidden, name],
    }),
  isolateComponent: (name) =>
    set({
      hidden: name
        ? get().spec.components.map((c) => c.name).filter((n) => n !== name)
        : [],
      selectedComponent: name,
    }),
  selectComponent: (name) => set({ selectedComponent: name }),
  hoverComponent: (name) => set({ hoveredComponent: name }),
  toggle: (key) => set({ [key]: !get()[key] } as Partial<AppState>),
  selectCandidate: (id) => set({ selectedCandidate: id }),
  setPrompt: (p) => set({ prompt: p }),
  setAgent: (a) => set({ agent: a }),

  startRun: async () => {
    const { enabledBands, prompt, agent, deviceId } = get();
    if (!enabledBands.length) {
      set({ error: "Select at least one band before running." });
      return;
    }
    set({
      ...EMPTY_RUN,
      running: true,
      planning: true,
      messages: [{ id: "u0", role: "user", kind: "text", text: prompt, ts: Date.now() }],
    });
    try {
      const res = await fetch("/api/run", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ prompt, bands: enabledBands, agent, deviceId }),
      });
      if (!res.ok) throw new Error((await res.json()).error ?? "run failed");
      const { runId } = await res.json();
      set({ runId });
      await get().poll();
    } catch (e) {
      set({ running: false, planning: false, error: e instanceof Error ? e.message : String(e) });
    }
  },

  sendNote: async (text) => {
    const runId = get().runId;
    if (!runId || !text.trim()) return;
    const res = await fetch("/api/run", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ runId, text }),
    });
    if (!res.ok) {
      set({ error: (await res.json()).error ?? "note not delivered" });
      return;
    }
    set({ error: null });
    await get().poll();
  },

  poll: async () => {
    const runId = get().runId;
    if (!runId) return;
    const res = await fetch(`/api/run?runId=${runId}`);
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      set({ running: false, error: body.error ?? "run snapshot unavailable" });
      return;
    }
    const snap = await res.json();
    // The user's prompt is local; the backend echoes only mid-run notes.
    const userMsg = get().messages.find((m) => m.id === "u0");
    const placements: Record<string, string> = snap.placements ?? {};
    const done = !!snap.done;
    set({
      jobs: snap.jobs ?? [],
      results: snap.results ?? {},
      placements,
      candidates: snap.candidates ?? [],
      planning: !!snap.planning,
      running: !done,
      engine: snap.engine ?? get().engine,
      messages: [...(userMsg ? [userMsg] : []), ...(snap.messages ?? [])],
      error: snap.status === "failed" ? "run failed — see the agent feed" : get().error,
      selectedCandidate:
        get().selectedCandidate ?? (Object.values(placements)[0] as string | undefined) ?? null,
    });
    if (done && !get().report && (snap.artifacts ?? []).includes("report.md")) {
      const r = await fetch(`/api/run?runId=${runId}&artifact=report.md`);
      if (r.ok) set({ report: await r.text() });
    }
  },

  reset: () => set({ ...EMPTY_RUN }),
}));

"use client";

import { KevinLockup } from "@/components/Logo";
import { useApp } from "@/lib/store";

export function TopBar() {
  const spec = useApp((s) => s.spec);
  const running = useApp((s) => s.running);
  const runId = useApp((s) => s.runId);
  const jobs = useApp((s) => s.jobs);
  const engine = useApp((s) => s.engine);
  const reset = useApp((s) => s.reset);
  const done = jobs.filter((j) => j.status === "complete").length;

  return (
    <header className="flex h-12 shrink-0 items-center gap-4 border-b border-slate-800/80 px-4">
      <div className="flex items-center gap-3">
        <KevinLockup height={20} className="text-slate-100" />
        <span className="hidden text-[11px] text-slate-500 sm:inline">AI antenna engineer</span>
      </div>

      <div className="ml-auto flex items-center gap-3 text-[11px]">
        <span className="font-mono text-slate-500">{spec.name}</span>
        {runId && (
          <span className="flex items-center gap-2 rounded-full border border-slate-800 px-2.5 py-1 font-mono text-[10px] text-slate-400">
            <span
              className={`h-1.5 w-1.5 rounded-full ${
                running ? "animate-pulse bg-sky-400" : "bg-emerald-400"
              }`}
            />
            {done}/{jobs.length} sims
            {engine && <span className="text-slate-600">· {engine}</span>}
          </span>
        )}
        {runId && !running && (
          <button
            onClick={reset}
            className="rounded-md border border-slate-800 px-2.5 py-1 text-slate-400 transition hover:border-slate-600 hover:text-slate-200"
          >
            Clear
          </button>
        )}
      </div>
    </header>
  );
}

"use client";

import { useRef } from "react";
import { useApp } from "@/lib/store";

export function SectionTitle({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-500">
      {children}
    </h2>
  );
}

/** Device card: what is loaded, and the one way to change it. */
function DeviceCard() {
  const spec = useApp((s) => s.spec);
  const setModel = useApp((s) => s.setModel);
  const modelName = useApp((s) => s.modelName);
  const uploadBlend = useApp((s) => s.uploadBlend);
  const uploading = useApp((s) => s.uploading);
  const deviceId = useApp((s) => s.deviceId);
  const fileRef = useRef<HTMLInputElement>(null);
  const [w, h, t] = spec.board.size_mm;

  return (
    <section className="border-b border-slate-800/80 px-4 py-3">
      <div className="mb-2 flex items-center justify-between">
        <SectionTitle>Device</SectionTitle>
        <button
          onClick={() => fileRef.current?.click()}
          disabled={uploading}
          className="text-[11px] text-sky-400 transition hover:text-sky-300 disabled:cursor-wait disabled:text-slate-500"
        >
          {uploading ? "Extracting…" : "Load .blend / .glb"}
        </button>
      </div>
      <div className="text-xs text-slate-200">{spec.name}</div>
      <div className="mt-0.5 font-mono text-[10px] text-slate-500">
        {w} × {h} × {t} mm · {spec.enclosure.frame} frame, {spec.enclosure.back} back ·{" "}
        {spec.components.length} parts
      </div>
      {modelName && (
        <div className="mt-1.5 flex items-center gap-2 font-mono text-[10px]">
          <span className="truncate text-emerald-400">{modelName}</span>
          <span className="shrink-0 text-slate-600">
            {deviceId ? "solver geometry" : "display only"}
          </span>
          <button
            onClick={() => setModel(null, null)}
            className="ml-auto shrink-0 text-slate-500 hover:text-slate-300"
          >
            clear
          </button>
        </div>
      )}
      <input
        ref={fileRef}
        type="file"
        accept=".blend,.glb,.gltf"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          e.target.value = "";
          if (!f) return;
          // .blend goes through the backend (extraction + classification);
          // a .glb is display-only and never reaches the solver.
          if (f.name.toLowerCase().endsWith(".blend")) void uploadBlend(f);
          else setModel(URL.createObjectURL(f), f.name);
        }}
      />
    </section>
  );
}

/** Band selection. Targets come from the backend's catalogue and are shown, not edited. */
function Bands() {
  const bands = useApp((s) => s.spec.requirements.bands);
  const enabled = useApp((s) => s.enabledBands);
  const toggleBand = useApp((s) => s.toggleBand);
  const focusBand = useApp((s) => s.focusBand);
  const setFocusBand = useApp((s) => s.setFocusBand);
  const running = useApp((s) => s.running);

  return (
    <section className="border-b border-slate-800/80 px-4 py-3">
      <div className="mb-2 flex items-baseline justify-between">
        <SectionTitle>Bands</SectionTitle>
        <span className="text-[10px] text-slate-600">
          {enabled.length} of {bands.length}
        </span>
      </div>
      <ul className="space-y-1">
        {bands.map((b) => {
          const on = enabled.includes(b.id);
          const isFocus = focusBand === b.id;
          return (
            <li
              key={b.id}
              className={`rounded-md border transition ${
                on ? "border-slate-800 bg-slate-900/50" : "border-transparent"
              } ${isFocus ? "ring-1 ring-sky-500/50" : ""}`}
            >
              <div className="flex items-center gap-2 px-2 py-1.5">
                <input
                  type="checkbox"
                  checked={on}
                  disabled={running}
                  onChange={() => toggleBand(b.id)}
                  className="accent-sky-500"
                />
                <span className="h-2 w-2 shrink-0 rounded-full" style={{ background: b.color }} />
                <button
                  onClick={() => on && setFocusBand(isFocus ? null : b.id)}
                  className={`truncate text-left text-xs ${
                    on ? "text-slate-200 hover:text-sky-300" : "text-slate-500"
                  }`}
                  title={on ? "focus this band in the viewer" : undefined}
                >
                  {b.name}
                </button>
                <span className="ml-auto shrink-0 font-mono text-[10px] text-slate-500">
                  {b.f_low_ghz}–{b.f_high_ghz}
                </span>
              </div>
              {on && (
                <dl className="grid grid-cols-3 gap-1 border-t border-slate-800/80 px-2 py-1.5 font-mono text-[10px]">
                  <div>
                    <dt className="text-slate-600">S11</dt>
                    <dd className="text-slate-300">≤ {b.s11_db_max} dB</dd>
                  </div>
                  <div>
                    <dt className="text-slate-600">efficiency</dt>
                    <dd className="text-slate-300">≥ {Math.round(b.efficiency_min * 100)}%</dd>
                  </div>
                  <div>
                    <dt className="text-slate-600">clearance</dt>
                    <dd className="text-slate-300">≥ {b.clearance_mm} mm</dd>
                  </div>
                </dl>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

export function SpecPanel() {
  return (
    <>
      <DeviceCard />
      <Bands />
    </>
  );
}

"use client";

import { sizeOf } from "@/lib/geometry";
import { useApp } from "@/lib/store";
import { SectionTitle } from "./SpecPanel";

const EM_LABEL: Record<string, string> = {
  pec: "PEC",
  lossy_metal: "lossy metal",
  dielectric: "dielectric",
  air: "air",
};

/** The device's parts as the solver sees them: hover/select/hide drive the viewer. */
export function ComponentTree() {
  const components = useApp((s) => s.spec.components);
  const hidden = useApp((s) => s.hidden);
  const selected = useApp((s) => s.selectedComponent);
  const toggleHidden = useApp((s) => s.toggleHidden);
  const selectComponent = useApp((s) => s.selectComponent);
  const hoverComponent = useApp((s) => s.hoverComponent);
  const isolateComponent = useApp((s) => s.isolateComponent);

  return (
    <section className="px-4 py-3">
      <div className="mb-2 flex items-center justify-between">
        <SectionTitle>Components</SectionTitle>
        {hidden.length > 0 && (
          <button
            onClick={() => isolateComponent(null)}
            className="text-[11px] text-sky-400 hover:text-sky-300"
          >
            show all
          </button>
        )}
      </div>

      <ul className="-mx-2">
        {components.map((c) => {
          const isHidden = hidden.includes(c.name);
          const isSel = selected === c.name;
          const s = sizeOf(c.bbox_mm);
          return (
            <li key={c.name}>
              <div
                onMouseEnter={() => hoverComponent(c.name)}
                onMouseLeave={() => hoverComponent(null)}
                onClick={() => selectComponent(isSel ? null : c.name)}
                className={`group flex cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-xs transition ${
                  isSel ? "bg-sky-500/10" : "hover:bg-slate-800/50"
                }`}
              >
                <span
                  className="h-2.5 w-2.5 shrink-0 rounded-sm ring-1 ring-white/15"
                  style={{ background: c.color, opacity: isHidden ? 0.3 : 1 }}
                />
                <span className={`truncate ${isHidden ? "text-slate-600" : "text-slate-200"}`}>
                  {c.label}
                </span>
                <span className="ml-auto shrink-0 font-mono text-[9px] text-slate-600">
                  {EM_LABEL[c.em]}
                </span>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleHidden(c.name);
                  }}
                  className={`w-7 shrink-0 text-right text-[10px] transition ${
                    isHidden
                      ? "text-slate-600 hover:text-slate-300"
                      : "text-slate-700 opacity-0 hover:text-slate-300 group-hover:opacity-100"
                  }`}
                  title={isHidden ? "show" : "hide"}
                >
                  {isHidden ? "show" : "hide"}
                </button>
              </div>
              {isSel && (
                <div className="mx-2 mb-1 space-y-0.5 rounded-md bg-slate-900/60 px-2.5 py-2 font-mono text-[10px] text-slate-400">
                  <div>
                    <span className="text-slate-600">node </span>
                    {c.name}
                  </div>
                  <div>
                    <span className="text-slate-600">size </span>
                    {s.map((v) => v.toFixed(1)).join(" × ")} mm
                  </div>
                  <div>
                    <span className="text-slate-600">origin </span>
                    {c.bbox_mm[0].map((v) => v.toFixed(1)).join(", ")} mm
                  </div>
                  {c.em === "dielectric" && (
                    <div>
                      <span className="text-slate-600">εr </span>
                      {c.epsilon_r}
                      <span className="text-slate-600"> · tan δ </span>
                      {c.loss_tangent}
                    </div>
                  )}
                  <button
                    onClick={() => isolateComponent(c.name)}
                    className="mt-1 text-sky-400 hover:text-sky-300"
                  >
                    isolate
                  </button>
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { KevinMark } from "@/components/Logo";
import { useApp } from "@/lib/store";
import { SectionTitle } from "./SpecPanel";

export function AgentPanel() {
  const prompt = useApp((s) => s.prompt);
  const setPrompt = useApp((s) => s.setPrompt);
  const startRun = useApp((s) => s.startRun);
  const poll = useApp((s) => s.poll);
  const running = useApp((s) => s.running);
  const planning = useApp((s) => s.planning);
  const messages = useApp((s) => s.messages);
  const jobs = useApp((s) => s.jobs);
  const error = useApp((s) => s.error);
  const runId = useApp((s) => s.runId);
  const agent = useApp((s) => s.agent);
  const setAgent = useApp((s) => s.setAgent);
  const sendNote = useApp((s) => s.sendNote);
  const [note, setNote] = useState("");
  const feedRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!running || !runId) return;
    const t = setInterval(() => void poll(), 600);
    return () => clearInterval(t);
  }, [running, runId, poll]);

  useEffect(() => {
    feedRef.current?.scrollTo({ top: feedRef.current.scrollHeight });
  }, [messages.length]);

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 border-b border-slate-800/80 px-4 py-3">
        <SectionTitle>Agent</SectionTitle>
        <div className="ml-auto flex rounded-md border border-slate-800 p-0.5">
          {(["mock", "devin"] as const).map((a) => (
            <button
              key={a}
              disabled={running}
              onClick={() => setAgent(a)}
              title={a === "devin" ? "Devin via API — needs backend/.env" : "offline heuristic agent on the backend"}
              className={`rounded px-2 py-0.5 text-[10px] transition disabled:cursor-not-allowed ${
                agent === a ? "bg-slate-800 text-slate-100" : "text-slate-500 hover:text-slate-300"
              }`}
            >
              {a === "mock" ? "Mock" : "Devin"}
            </button>
          ))}
        </div>
      </header>

      <div ref={feedRef} className="flex-1 space-y-1.5 overflow-y-auto px-4 py-3">
        {!messages.length && (
