"use client";

import { Fragment, type ReactNode } from "react";

/** `**bold**`, `` `code` `` and `_em_` inside one line. */
function inline(text: string): ReactNode[] {
  const out: ReactNode[] = [];
  const re = /(\*\*[^*]+\*\*|`[^`]+`|_[^_]+_)/g;
  let last = 0;
  let m: RegExpExecArray | null;
  let k = 0;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index));
    const t = m[0];
    if (t.startsWith("**")) out.push(<strong key={k++} className="text-slate-100">{t.slice(2, -2)}</strong>);
    else if (t.startsWith("`")) out.push(<code key={k++} className="rounded bg-slate-800/80 px-1 font-mono text-[10px] text-slate-200">{t.slice(1, -1)}</code>);
    else out.push(<em key={k++} className="text-slate-500">{t.slice(1, -1)}</em>);
    last = m.index + t.length;
  }
  if (last < text.length) out.push(text.slice(last));
  return out;
}

/**
 * Just enough Markdown for the backend's report.md: ATX headings, bullet
 * lists, pipe tables, paragraphs. Anything else renders as a paragraph.
 */
export function Markdown({ source }: { source: string }) {
  const lines = source.replace(/\r/g, "").split("\n");
  const blocks: ReactNode[] = [];
  let i = 0;
  let k = 0;

  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) {
      i++;
      continue;
    }
    const h = /^(#{1,6})\s+(.*)$/.exec(line);
    if (h) {
      const level = h[1].length;
      const cls =
        level === 1
          ? "mt-1 text-sm font-semibold text-slate-100"
          : level === 2
            ? "mt-4 text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-400"
            : "mt-3 text-xs font-semibold text-slate-200";
      blocks.push(<div key={k++} className={cls}>{inline(h[2])}</div>);
      i++;
      continue;
    }
    if (/^\s*[-*]\s+/.test(line) || /^\s*\d+\.\s+/.test(line)) {
      const ordered = /^\s*\d+\./.test(line);
      const items: string[] = [];
      while (i < lines.length && (/^\s*[-*]\s+/.test(lines[i]) || /^\s*\d+\.\s+/.test(lines[i]))) {
        items.push(lines[i].replace(/^\s*([-*]|\d+\.)\s+/, ""));
        i++;
      }
      const Tag = ordered ? "ol" : "ul";
      blocks.push(
        <Tag key={k++} className={`ml-4 space-y-0.5 ${ordered ? "list-decimal" : "list-disc"} text-slate-300`}>
          {items.map((it, j) => <li key={j}>{inline(it)}</li>)}
        </Tag>,
      );
      continue;
    }
    if (line.trim().startsWith("|")) {
      const rows: string[][] = [];
      while (i < lines.length && lines[i].trim().startsWith("|")) {
        const cells = lines[i].trim().slice(1, -1).split("|").map((c) => c.trim());
        if (!cells.every((c) => /^:?-+:?$/.test(c))) rows.push(cells);
        i++;
      }
      const [head, ...body] = rows;
      blocks.push(
        <div key={k++} className="my-1.5 overflow-x-auto">
          <table className="w-full border-collapse text-[10.5px]">
            <thead>
              <tr>
                {head.map((c, j) => (
                  <th key={j} className="border-b border-slate-800 px-2 py-1 text-left font-medium text-slate-500">{inline(c)}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {body.map((r, ri) => (
                <tr key={ri} className="border-b border-slate-900">
                  {r.map((c, j) => (
                    <td key={j} className={`px-2 py-1 ${j === 0 ? "text-slate-400" : "font-mono text-slate-200"}`}>{inline(c)}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>,
      );
      continue;
    }
    // paragraph: consecutive non-empty, non-block lines
    const para: string[] = [];
    while (i < lines.length && lines[i].trim() && !/^(#{1,6}\s|\s*[-*]\s|\s*\d+\.\s|\s*\|)/.test(lines[i])) {
      para.push(lines[i]);
      i++;
    }
    blocks.push(<p key={k++} className="text-slate-300">{inline(para.join(" "))}</p>);
  }

  return <div className="space-y-1.5 text-[11px] leading-relaxed">{blocks.map((b, j) => <Fragment key={j}>{b}</Fragment>)}</div>;
}

"use client";

import { useMemo, useState } from "react";
import { useApp } from "@/lib/store";
import { Markdown } from "./Markdown";
import { S11Chart } from "./S11Chart";
import { SpectrumStrip } from "./SpectrumStrip";

function Verdict({ ok }: { ok: boolean }) {
  return (
    <span
      className={`rounded px-1.5 py-0.5 text-[9px] font-bold ${
        ok ? "bg-emerald-500/15 text-emerald-400" : "bg-red-500/15 text-red-400"
      }`}
    >
      {ok ? "PASS" : "FAIL"}
    </span>
  );
}

function Empty({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex h-full items-center justify-center px-4 text-center text-[11px] text-slate-600">
      {children}
    </div>
  );
}

/** Every simulated candidate, chosen ones first, then by band and S11. */
function ResultsTable() {
  const candidates = useApp((s) => s.candidates);
  const results = useApp((s) => s.results);
  const placements = useApp((s) => s.placements);
  const anchors = useApp((s) => s.anchors);
  const bands = useApp((s) => s.spec.requirements.bands);
  const selected = useApp((s) => s.selectedCandidate);
  const select = useApp((s) => s.selectCandidate);

  const rows = useMemo(
    () =>
      candidates
        .map((c) => ({
          c,
          r: results[c.candidate_id],
          band: bands.find((b) => b.id === c.band_id),
          anchor: anchors.find((a) => a.id === c.anchor_id),
          chosen: Object.values(placements).includes(c.candidate_id),
        }))
        .sort(
          (a, b) =>
            Number(b.chosen) - Number(a.chosen) ||
            (a.band?.f_low_ghz ?? 0) - (b.band?.f_low_ghz ?? 0) ||
            (a.r?.s11_min_db ?? 0) - (b.r?.s11_min_db ?? 0),
        ),
    [candidates, results, placements, bands, anchors],
  );

  if (!rows.length) return <Empty>Simulated candidates appear here as the agent proposes them.</Empty>;

  const num = "px-2 py-1.5 text-right font-mono text-slate-400";
  return (
    <div className="h-full overflow-auto">
      <table className="w-full border-collapse text-[10px]">
        <thead className="sticky top-0 bg-slate-950 text-slate-500">
          <tr className="[&>th]:px-2 [&>th]:py-1.5 [&>th]:text-left [&>th]:font-medium">
            <th>Band</th>
            <th>Position</th>
            <th>Type</th>
            <th className="text-right">S11 dB</th>
            <th className="text-right">f₀ GHz</th>
            <th className="text-right">BW MHz</th>
            <th className="text-right">Eff</th>
            <th className="text-right">Gain dBi</th>
            <th className="text-right">VSWR</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {rows.map(({ c, r, band, anchor, chosen }) => {
            const isSel = selected === c.candidate_id;
            const pending = !r || r.status === "queued" || r.status === "running";
            const failed = r?.status === "failed";
            return (
              <tr
                key={c.candidate_id}
                onClick={() => select(c.candidate_id)}
                title={c.rationale || undefined}
                className={`cursor-pointer border-t border-slate-900 transition ${
                  isSel ? "bg-sky-500/10" : "hover:bg-slate-900/70"
                } ${pending ? "opacity-50" : ""}`}
              >
                <td className="px-2 py-1.5">
                  <span className="flex items-center gap-1.5">
                    <span className="h-2 w-2 shrink-0 rounded-full" style={{ background: band?.color }} />
                    <span className="text-slate-300">{band?.short ?? c.band_id}</span>
                    {chosen && (
                      <span className="rounded bg-sky-500/20 px-1 text-[8px] font-bold text-sky-300">
                        CHOSEN
                      </span>
                    )}
                  </span>
                </td>
                <td className="px-2 py-1.5 text-slate-400">
                  {anchor?.label ?? c.anchor_id}
                  <span className="ml-1 font-mono text-slate-600">
                    {c.position_mm.map((v) => v.toFixed(0)).join(",")}
                  </span>
                </td>
                <td className="px-2 py-1.5 font-mono text-slate-400">
                  {c.antenna_type} · {c.length_mm} mm
                </td>
                {pending || failed ? (
                  <td colSpan={6} className="px-2 py-1.5 font-mono text-slate-600">
                    {failed ? r.notes || "solve failed" : r?.status === "running" ? "simulating…" : "queued"}
                  </td>
                ) : (
                  <>
                    <td className={`${num} text-slate-200`}>{r.s11_min_db.toFixed(1)}</td>
                    <td className={num}>{r.resonant_ghz.toFixed(3)}</td>
                    <td className={num}>{Math.round(r.bandwidth_mhz)}</td>
                    <td className={num}>{(r.efficiency * 100).toFixed(0)}%</td>
                    <td className={num}>{r.peak_gain_dbi.toFixed(1)}</td>
                    <td className={num}>{r.vswr.toFixed(2)}</td>
                  </>
                )}
                <td className="px-2 py-1.5 text-right">
                  {!pending && !failed && <Verdict ok={r.meets_requirements} />}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/** The agent's own report.md, once the run has finished. */
function ReportView() {
  const report = useApp((s) => s.report);
  const running = useApp((s) => s.running);
  const runId = useApp((s) => s.runId);

  if (!report) {
    return (
      <Empty>
        {running ? "The report is written when the run finishes." : "Run a placement study to get a report."}
      </Empty>
    );
  }
  return (
    <div className="h-full overflow-auto px-4 py-3">
      <Markdown source={report} />
      <a
        href={`/api/run?runId=${runId}&artifact=report.md`}
        target="_blank"
        rel="noreferrer"
        className="mt-4 inline-block text-[10px] text-sky-400 hover:text-sky-300"
      >
        open report.md ↗
      </a>
    </div>
  );
}

